import{z as A,x as s,o as n,c as p,q as i,j as o,D as e,d as B,s as r,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"关系借贷","description":"","frontmatter":{"title":"关系借贷","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/relationship-lending.md","filePath":"econ/relationship-lending.md","lastUpdated":1791413859000}'),d={name:"econ/relationship-lending.md"};function F(C,a,m,h,D,c){const t=s("Mermaid");return n(),p("div",null,[a[2]||(a[2]=i('<h1 id="关系借贷" tabindex="-1">关系借贷 <a class="header-anchor" href="#关系借贷" aria-label="Permalink to &quot;关系借贷&quot;">​</a></h1><div class="epigraph"><p>跨期的银行关系用软信息换取危机时的保险：平时可能付更高利息或接受套牢，换的是可验证条款写不尽的那次展期。</p><footer>—— Petersen and Rajan, The Benefits of Lending Relationships, Journal of Finance 1994；Boot, Relationship Banking, Journal of Financial Intermediation 2000</footer></div><p><a href="/econ/bank-vs-public-debt">上一课</a>给出套牢与监督的权衡。本课缺口是跨期：关系如何生产软信息、如何在周期里平滑，以及竞争如何削弱关系。不重推 Diamond 的声誉毕业，不写银行挤兑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开债与交易贷款依赖可验证信息。中小企业、创新项目的信息是软的（判断、过程），难以转卖。Petersen–Rajan（1994）：关系降低中小企业的信贷约束，早期可能付较高成本，后期随信息积累改善。Boot：关系是含糊合同，状态不可写尽时用权威与声誉执行。缺口是把上一课的「银行」分成关系型与交易型，并标明竞争、可转让贷款如何把关系拆掉。</p><p><span class="marginnote">直觉类比：关系借贷像老字号与街坊的赊账——老板娘记得谁家工资几号发、谁从来说话算数。这些「记在脑子里」的软信息写不进合同，也带不走，却让她敢在对方手头紧的月份继续赊；换一家生店，这套记录就清零重来。</span></p><p><span class="marginnote">软信息难以在组织内传递，所以关系常绑定信贷员与分支——这是银行内部组织，本课只取对借款企业的含义：换银行会损失信息资本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跨期补贴：初期贷款 NPV 对银行可为负（投资于信息），靠后期信息租金收回。竞争加剧则后期租金消失，银行不愿付初期补贴——Petersen–Rajan 强调市场力量对关系的非单调影响。可转让与证券化把贷款卖出，监测激励下降，下一课发起–分销会写极端。</p><p>对企业：单一关系加深信息、加重套牢；多银行减轻套牢、稀释信息投资。与期限：关系使短债的展期更像保险而不是挤兑；失去关系之后，同一短债结构变成 Diamond 的流动性风险。</p><p><span class="marginnote">常见误区：容易以为「同时跟多家银行来往更安全、议价更便宜」。多银行确实减轻套牢，但也稀释了每家银行的信息投资：谁都不肯做初期亏本的补贴贷款，因为收回租金的把握变小。对信息不透明的中小企业，银行数量往往不是越多越好。</span></p>',11)),(n(),o(l,null,{default:e(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOFT%5B%22%E8%BD%AF%E4%BF%A1%E6%81%AF%22%5D%20--%3E%20REL%5B%22%E5%85%B3%E7%B3%BB%E6%8A%95%E8%B5%84%22%5D%0A%20%20REL%20--%3E%20INS%5B%22%E5%8D%B1%E6%9C%BA%E5%B1%95%E6%9C%9F%E4%BF%9D%E9%99%A9%22%5D%0A%20%20REL%20--%3E%20HU%5B%22%E5%90%8E%E6%9C%9F%E7%A7%9F%E9%87%91%20%2F%20%E5%A5%97%E7%89%A2%22%5D%0A%20%20COMP%5B%22%E4%BF%A1%E8%B4%B7%E5%B8%82%E5%9C%BA%E7%AB%9E%E4%BA%89%22%5D%20--%3E%20WEAK%5B%22%E5%88%9D%E6%9C%9F%E8%A1%A5%E8%B4%B4%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SALE%5B%22%E8%B4%B7%E6%AC%BE%E5%8F%AF%E8%BD%AC%E8%AE%A9%22%5D%20--%3E%20MON%5B%22%E7%9B%91%E6%B5%8B%E6%BF%80%E5%8A%B1%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"资本预算：有关系的企业，APV 里展期失败概率低于公开市场模型。没有关系却按关系假设去折现，会低估流动性副作用。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是不可转让的信息资本与隐含合同。双方用未来生意约束今天的机会主义：企业不把银行当一次性拍卖，银行不在第一次坏消息时逼债。宏观冲击若大到银行自己资本不足，隐含合同破裂——关系不是国家风险保险。Rajan 套牢是关系的阴暗面：信息资本提高退出成本，利率可以高于竞争水平。",-1)),(n(),o(l,null,{default:e(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E5%88%9D%E6%9C%9F%EF%BC%9A%E9%93%B6%E8%A1%8C%E4%BA%8F%E6%9C%AC%E6%94%BE%E8%B4%B7%EF%BC%8C%E6%8A%95%E8%B5%84%E4%BA%8E%E4%BA%86%E8%A7%A3%E4%BC%81%E4%B8%9A%22%5D%20--%3E%20T1%5B%22%E4%B8%AD%E6%9C%9F%EF%BC%9A%E8%BD%AF%E4%BF%A1%E6%81%AF%E7%A7%AF%E7%B4%AF%EF%BC%8C%E7%9B%91%E6%B5%8B%E5%8A%A0%E6%B7%B1%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E6%AD%A3%E5%B8%B8%E5%B9%B4%E6%99%AF%EF%BC%9A%E9%93%B6%E8%A1%8C%E6%94%B6%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E5%9B%9E%E6%9C%AC%22%5D%0A%20%20T1%20--%3E%20T3%5B%22%E5%8D%B1%E6%9C%BA%EF%BC%9A%E9%93%B6%E8%A1%8C%E5%B1%95%E6%9C%9F%EF%BC%8C%E4%BC%81%E4%B8%9A%E6%8B%BF%E5%88%B0%E4%BF%9D%E9%99%A9%22%5D%0A%20%20T1%20--%3E%20HU%5B%22%E4%BC%81%E4%B8%9A%E6%83%B3%E6%8D%A2%E9%93%B6%E8%A1%8C%EF%BC%9A%E4%BF%A1%E6%81%AF%E8%B5%84%E6%9C%AC%E5%B8%A6%E4%B8%8D%E8%B5%B0%EF%BC%8C%E8%A2%AB%E5%A5%97%E7%89%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">术语翻译：「信息租金」就是银行在后期收到的、高于资金成本的那块利差，是它初期亏本放贷换来的回报。若市场竞争把这块租金抹平，初期补贴就没人肯出——所以市场力量与关系借贷的关系是非单调的：适度竞争促进关系，过度竞争拆掉关系。</span></p><p>与优序：关系债信息敏感度低于公开股、也常低于公开债，排在内部资金之后、公募之前，是优序的银行版。柠檬在关系里被监测缓解，不是消失。</p><h3 id="关系不是「非经济的人情」" tabindex="-1">关系不是「非经济的人情」 <a class="header-anchor" href="#关系不是「非经济的人情」" aria-label="Permalink to &quot;关系不是「非经济的人情」&quot;">​</a></h3><p>租金与保险都可以写进 Tirole 的融资合同：不可验证努力靠长期博弈。人情叙事不增加机制。本课禁止把关系写成与利率无关的偏好。</p><p><span class="marginnote">Sharpe、Rajan 的套牢模型与 Petersen–Rajan 的实证对象（美国中小企业）应分开读：机制是信息租金，度量是信贷可得性与利率，不是「有没有一起吃过饭」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成中小企业政策。下一课评级机构：公开债用可验证的第三方意见替代关系软信息，另一套代理（发行方付费）随之出现。</p><p>后课默认：关系用软信息换展期保险，竞争与可转让削弱它；套牢与保险并存。展期风险依赖是否真有关系，不能只看期限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关系借贷投资于软信息，跨期补贴换危机保险，也产生退出成本。</li><li>竞争可能减少关系投资；贷款转卖削弱监测。</li><li>对企业资本结构：关系债介于内部资金与公开债之间。</li><li>出处：Petersen and Rajan, <em>JF</em> 1994；Boot, <em>JFI</em> 2000；Rajan, <em>JF</em> 1992。</li></ul>',10))])}const T=A(d,[["render",F]]);export{f as __pageData,T as default};
